param([string]$Root=('D:\Artifacts\KnowledgeClipper\actual-harness-offline\finalize-tool-'+[Guid]::NewGuid().ToString('N')))
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$tool=Join-Path $PSScriptRoot 'Finalize-DesktopObservationStaging.ps1'
function J($p,$v){[IO.Directory]::CreateDirectory((Split-Path -Parent $p))|Out-Null;[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 10)+[Environment]::NewLine,[Text.UTF8Encoding]::new($false))}
function Get-Sha256($p){(Get-FileHash $p -Algorithm SHA256).Hash}
function Fixture($name){$r=Join-Path $Root $name;$s=Join-Path $r 'staging';[IO.Directory]::CreateDirectory($s)|Out-Null;[IO.File]::WriteAllText((Join-Path $s 'a.txt'),'a');[IO.File]::WriteAllText((Join-Path $s '知识.txt'),'知识');$proof=[ordered]@{status='PASS';files=2;missing=@();extra=@();hashMismatch=@();integrationValid=$true;candidateManifestPresent=$false;actualExecuted=$false;externalCalls=0};$p1=Join-Path $r 'merge.json';$p2=Join-Path $r 'independent.json';J $p1 $proof;J $p2 $proof;$dm=Join-Path $r 'desktop-manifest.json';$cm=Join-Path $r 'core-manifest.json';J $dm ([ordered]@{candidateId='desktop-source';payload=[ordered]@{treeSha256='d'*64}});J $cm ([ordered]@{candidateId='core-source';payload=[ordered]@{treeSha256='c'*64};observationSdk=[ordered]@{freezeManifestSha256='f'*64}});[pscustomobject]@{root=$r;staging=$s;p1=$p1;p2=$p2;dm=$dm;cm=$cm;receipt=Join-Path $r 'outside\receipt.json'}}
function InvokeTool($f,[switch]$validate,[string]$expected,[string]$mergeSha,[string]$desktopPath,[string]$desktopId='desktop-source',[string]$coreId='core-source',[string]$coreTree,[string]$freeze){& $tool -Staging $f.staging -ExpectedStaging $(if($expected){$expected}else{$f.staging}) -Receipt $f.receipt -MergeReceipt $f.p1 -IndependentMergeReceipt $f.p2 -DesktopSourceManifest $(if($desktopPath){$desktopPath}else{$f.dm}) -CoreSourceManifest $f.cm -ExpectedDesktopSourceManifestSha256 (Get-Sha256 $f.dm) -ExpectedCoreSourceManifestSha256 (Get-Sha256 $f.cm) -ExpectedDesktopCandidateId $desktopId -ExpectedCoreCandidateId $coreId -ExpectedCorePayloadTreeSha256 $(if($coreTree){$coreTree}else{'c'*64}) -ExpectedSdkFreezeManifestSha256 $(if($freeze){$freeze}else{'f'*64}) -ExpectedMergeReceiptSha256 $(if($mergeSha){$mergeSha}else{Get-Sha256 $f.p1}) -ExpectedIndependentReceiptSha256 (Get-Sha256 $f.p2) -ExpectedPayloadFiles 2 -ValidateOnly:$validate}
$good=Fixture 'good';$file=Get-Item (Join-Path $good.staging 'a.txt');$before=Get-Sha256 $file.FullName;$beforeTime=$file.LastWriteTimeUtc.Ticks;InvokeTool $good|Out-Null;if(!(Test-Path (Join-Path $good.staging 'candidate-file-manifest.v1.json'))-or!(Test-Path $good.receipt)-or(Get-Sha256 $file.FullName)-ne$before-or(Get-Item $file.FullName).LastWriteTimeUtc.Ticks-ne$beforeTime){throw 'good-finalize'}
$failures=0;try{InvokeTool $good|Out-Null}catch{$failures++}
$extra=Fixture 'extra';[IO.File]::WriteAllText((Join-Path $extra.staging 'unexpected.txt'),'x');try{InvokeTool $extra -validate|Out-Null}catch{$failures++}
$receipt=Fixture 'receipt';[IO.Directory]::CreateDirectory((Split-Path -Parent $receipt.receipt))|Out-Null;[IO.File]::WriteAllText($receipt.receipt,'existing');try{InvokeTool $receipt -validate|Out-Null}catch{$failures++}
$wrong=Fixture 'wrong-target';try{InvokeTool $wrong -validate -expected (Join-Path $wrong.root 'different')|Out-Null}catch{$failures++}
$hash=Fixture 'hash-drift';try{InvokeTool $hash -validate -mergeSha ('0'*64)|Out-Null}catch{$failures++}
$missing=Fixture 'missing';Remove-Item -LiteralPath (Join-Path $missing.staging 'a.txt');try{InvokeTool $missing -validate|Out-Null}catch{$failures++}
$path=Fixture 'source-path';try{InvokeTool $path -validate -desktopPath $path.p1|Out-Null}catch{$failures++}
$desktopId=Fixture 'desktop-id';try{InvokeTool $desktopId -validate -desktopId 'wrong'|Out-Null}catch{$failures++}
$coreId=Fixture 'core-id';try{InvokeTool $coreId -validate -coreId 'wrong'|Out-Null}catch{$failures++}
$tree=Fixture 'core-tree';try{InvokeTool $tree -validate -coreTree ('0'*64)|Out-Null}catch{$failures++}
$freeze=Fixture 'sdk-freeze';try{InvokeTool $freeze -validate -freeze ('0'*64)|Out-Null}catch{$failures++}
if($failures-ne11){throw 'negative-count'}
$source=[IO.File]::ReadAllText($tool);foreach($forbidden in @('Copy-Item','Remove-Item','Move-Item','-Force')){if($source.Contains($forbidden,[StringComparison]::OrdinalIgnoreCase)){throw ('payload-write-primitive:'+ $forbidden)}}
[ordered]@{status='PASS';positive=1;negative=11;payloadMutation=0;payloadTimestampMutation=0;candidateRootsCreated=0;actualExecuted=$false}|ConvertTo-Json
